import base64,re

def b64_decode(s):
    s=re.sub(r"\s+","",s or "")
    s+="="*(-len(s)%4)
    return base64.b64decode(s).decode("utf-8",errors="replace")

def b64_encode(t):
    return base64.b64encode(t.encode("utf-8")).decode("ascii")

def assert_non_empty(text):
    if not (text or "").strip():
        raise ValueError("Refusing empty content")
